<?php
declare(strict_types=1);
$groups=['header'=>[],'footer'=>[]];$children=[];
foreach(($items??[]) as $row){if(empty($row['parent_id']))$groups[$row['location']][]=$row;else $children[(int)$row['parent_id']][]=$row;}
$editingId=(int)($editItem['id']??0);
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Menü yönetimi</title>
<style>
*{box-sizing:border-box}body{font-family:system-ui,-apple-system,sans-serif;background:#f4f7f5;color:#26332b;margin:0}.wrap{max-width:1180px;margin:30px auto;padding:0 16px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.top a,.btn{display:inline-block;background:#176b50;color:#fff;text-decoration:none;border:0;border-radius:9px;padding:10px 14px;font:700 14px system-ui;cursor:pointer}.panel{background:#fff;padding:20px;border-radius:14px;margin:16px 0;box-shadow:0 5px 22px #20332c08}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{min-width:0}.field.full{grid-column:1/-1}label{display:block;font-size:13px;font-weight:750;margin:3px 0 6px}input,select{width:100%;min-width:0;padding:11px;border:1px solid #dfe6e0;border-radius:8px;font:inherit;background:#fff}.hint{font-size:12px;color:#718078;margin-top:5px}.check{display:flex;align-items:center;gap:8px;margin:12px 0}.check input{width:auto}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn.secondary{background:#eaf1ed;color:#294338}.btn.danger{background:#a43}.btn.warning{background:#8b671c}.muted{color:#718078}.section-title{margin:0 0 5px}.menu-group{border:1px solid #e5ece7;border-radius:12px;padding:14px;margin-top:14px}.menu-group h3{margin:0 0 10px;font-size:16px}.sortable-list{list-style:none;margin:0;padding:0;min-height:10px}.menu-row{border:1px solid #e6ece8;border-radius:10px;background:#fff;padding:11px 12px;margin:7px 0;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.menu-row.dragging{opacity:.45}.menu-row.drop-target{border-color:#167c80;background:#eff8f5}.drag-handle{cursor:grab;color:#718078;font-size:20px;user-select:none}.menu-info{flex:1;min-width:160px}.menu-info strong{display:block}.menu-info small{color:#718078;overflow-wrap:anywhere}.menu-actions{display:flex;gap:6px;flex-wrap:wrap}.menu-actions form{margin:0}.child-list{margin:6px 0 6px 35px;padding:5px 10px;border-left:2px solid #dcebe3;background:#f8fbf9;border-radius:0 9px 9px 0}.child-list:empty:after{content:'Alt menü öğelerini buraya sürükleyin';display:block;color:#a0aaa4;font-size:12px;padding:8px}.status{font-size:12px;font-weight:800}.save-order{margin-top:12px}.save-state{font-size:13px;color:#176b50;margin-left:8px}@media(max-width:650px){.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.panel{padding:15px}.wrap{margin:18px auto}.menu-row{align-items:flex-start}.menu-actions{width:100%;padding-left:30px}}
</style></head><body><main class="wrap">
<div class="top"><div><h1>Menü yönetimi</h1><p class="muted">Menüleri sürükleyerek sıralayın; bir öğeyi başka bir ana menünün altına taşıyarak açılır menü oluşturun.</p></div><a href="/admin">Yönetim paneli</a></div>
<section class="panel" id="menu-form"><h2 class="section-title"><?= $editingId?'Menü öğesini düzenle':'Yeni menü öğesi ekle' ?></h2>
<p class="hint">Sistem sayfası veya yayınlanmış CMS sayfası seçebilirsiniz. Alt menü için bir ana menü seçin.</p>
<form method="post" action="/admin/navigation/save"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $editingId ?>">
<div class="form-grid">
<div class="field"><label for="menu-label">Menüde görünecek ad</label><input id="menu-label" name="label" maxlength="120" required value="<?= e($editItem['label']??'') ?>" placeholder="Örn. Hakkımızda"></div>
<div class="field"><label for="menu-page">Sistem veya içerik sayfası</label><select id="menu-page"><option value="">Özel bağlantı (URL girin)</option><optgroup label="Sistem sayfaları"><?php foreach(($systemPages??[]) as $page): ?><option value="<?= e($page['url']) ?>" <?= ($editItem['url']??'')===$page['url']?'selected':'' ?>><?= e($page['label']) ?> — <?= e($page['url']) ?></option><?php endforeach; ?></optgroup><?php if(!empty($cmsPages)): ?><optgroup label="Yayınlanmış içerik sayfaları"><?php foreach($cmsPages as $page): ?><option value="/page/<?= e($page['slug']) ?>" <?= ($editItem['url']??'')==='/page/'.$page['slug']?'selected':'' ?>><?= e($page['title']) ?></option><?php endforeach; ?></optgroup><?php endif; ?></select></div>
<div class="field full"><label for="menu-url">Bağlantı adresi</label><input id="menu-url" name="url" required value="<?= e($editItem['url']??'') ?>" placeholder="/konaklamalar veya https://ornek.com"></div>
<div class="field"><label for="menu-location">Menü konumu</label><select id="menu-location" name="location"><option value="header" <?= ($editItem['location']??'header')==='header'?'selected':'' ?>>Üst menü</option><option value="footer" <?= ($editItem['location']??'')==='footer'?'selected':'' ?>>Alt menü</option></select></div>
<div class="field"><label for="menu-parent">Üst menü / ana öğe</label><select id="menu-parent" name="parent_id"><option value="0">Ana menü öğesi (üst seviye)</option><?php foreach(($items??[]) as $parent): if((int)$parent['id']===$editingId||!empty($parent['parent_id']))continue; ?><option value="<?= (int)$parent['id'] ?>" data-location="<?= e($parent['location']) ?>" <?= (int)($editItem['parent_id']??0)===(int)$parent['id']?'selected':'' ?>><?= e($parent['label']) ?> · <?= $parent['location']==='footer'?'Alt menü':'Üst menü' ?></option><?php endforeach; ?></select><div class="hint">Bir ana öğe seçerseniz bu bağlantı onun açılır alt menüsünde görünür.</div></div>
<div class="field"><label for="menu-target">Bağlantı açılışı</label><select id="menu-target" name="target"><option value="_self" <?= ($editItem['target']??'_self')==='_self'?'selected':'' ?>>Aynı sekmede</option><option value="_blank" <?= ($editItem['target']??'')==='_blank'?'selected':'' ?>>Yeni sekmede</option></select></div>
<div class="field"><label for="menu-sort">Sıralama</label><input id="menu-sort" type="number" name="sort_order" min="0" max="9999" value="<?= (int)($editItem['sort_order']??10) ?>"></div>
<div class="field"><label>Yayın durumu</label><label class="check"><input type="checkbox" name="is_active" value="1" <?= !isset($editItem['is_active'])||(int)$editItem['is_active']===1?'checked':'' ?>> Menüde aktif olarak göster</label></div>
</div><div class="actions"><button class="btn" type="submit"><?= $editingId?'Değişiklikleri kaydet':'Menüyü ekle' ?></button><?php if($editingId): ?><a class="btn secondary" href="/admin/navigation">Vazgeç</a><?php endif; ?></div>
</form></section>
<section class="panel"><h2 class="section-title">Menü sıralaması ve hiyerarşisi</h2><p class="hint">Tutma simgesinden sürükleyip aynı seviyede sıralayın veya başka bir ana menünün alt listesine bırakın. Değişiklikleri kaydetmeyi unutmayın.</p>
<?php foreach(['header'=>'Üst menü','footer'=>'Alt menü'] as $location=>$heading): ?><div class="menu-group"><h3><?= $heading ?></h3><ol class="sortable-list root-list" data-location="<?= $location ?>" data-parent="0">
<?php foreach($groups[$location] as $root): ?><li class="menu-node" data-id="<?= (int)$root['id'] ?>" draggable="true"><div class="menu-row"><span class="drag-handle" title="Sürükleyerek sırala">⠿</span><div class="menu-info"><strong><?= e($root['label']) ?></strong><small><?= e($root['url']) ?> · #<?= (int)$root['id'] ?></small></div><span class="status" style="color:<?= (int)$root['is_active']?'#176b50':'#a43' ?>"><?= (int)$root['is_active']?'Aktif':'Pasif' ?></span><div class="menu-actions"><a class="btn secondary" href="/admin/navigation?edit=<?= (int)$root['id'] ?>#menu-form">Düzenle</a><form method="post" action="/admin/navigation/toggle"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$root['id'] ?>"><button class="btn warning" type="submit"><?= (int)$root['is_active']?'Pasifleştir':'Etkinleştir' ?></button></form><form method="post" action="/admin/navigation/delete" onsubmit="return confirm('Bu menü öğesi silinsin mi?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$root['id'] ?>"><button class="btn danger" type="submit">Sil</button></form></div></div>
<ol class="sortable-list child-list" data-location="<?= $location ?>" data-parent="<?= (int)$root['id'] ?>"><?php foreach(($children[(int)$root['id']]??[]) as $child): ?><li class="menu-node" data-id="<?= (int)$child['id'] ?>" draggable="true"><div class="menu-row"><span class="drag-handle">⠿</span><div class="menu-info"><strong>↳ <?= e($child['label']) ?></strong><small><?= e($child['url']) ?> · Alt menü</small></div><span class="status" style="color:<?= (int)$child['is_active']?'#176b50':'#a43' ?>"><?= (int)$child['is_active']?'Aktif':'Pasif' ?></span><div class="menu-actions"><a class="btn secondary" href="/admin/navigation?edit=<?= (int)$child['id'] ?>#menu-form">Düzenle</a><form method="post" action="/admin/navigation/toggle"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$child['id'] ?>"><button class="btn warning" type="submit"><?= (int)$child['is_active']?'Pasifleştir':'Etkinleştir' ?></button></form><form method="post" action="/admin/navigation/delete" onsubmit="return confirm('Bu menü öğesi silinsin mi?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$child['id'] ?>"><button class="btn danger" type="submit">Sil</button></form></div></div></li><?php endforeach; ?></ol>
</li><?php endforeach; ?></ol></div><?php endforeach; ?>
<button class="btn save-order" id="saveMenuOrder" type="button">Sıralamayı kaydet</button><span class="save-state" id="saveMenuState" aria-live="polite"></span>
</section><p><a href="/admin">Yönetim paneli</a></p></main>
<script>
(function(){
var picker=document.getElementById('menu-page'),url=document.getElementById('menu-url'),loc=document.getElementById('menu-location'),parent=document.getElementById('menu-parent');
if(picker&&url)picker.addEventListener('change',function(){if(picker.value)url.value=picker.value;});
function filterParents(){if(!parent||!loc)return;Array.from(parent.options).forEach(function(o){if(o.value!=='0')o.hidden=o.dataset.location!==loc.value;});if(parent.selectedOptions[0]&&parent.selectedOptions[0].hidden)parent.value='0';}
if(loc)loc.addEventListener('change',filterParents);filterParents();
var dragged=null;
document.querySelectorAll('.menu-node').forEach(function(node){
 node.addEventListener('dragstart',function(e){dragged=node;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',node.dataset.id);node.classList.add('dragging');});
 node.addEventListener('dragend',function(){node.classList.remove('dragging');document.querySelectorAll('.drop-target').forEach(function(x){x.classList.remove('drop-target')});dragged=null;});
});
document.querySelectorAll('.sortable-list').forEach(function(list){
 list.addEventListener('dragover',function(e){if(!dragged||dragged.parentElement!==list)return;e.preventDefault();var after=null;Array.from(list.querySelectorAll(':scope > .menu-node')).forEach(function(el){if(el===dragged)return;var r=el.getBoundingClientRect();if(e.clientY<r.top+r.height/2&&!after)after=el;});if(after)list.insertBefore(dragged,after);else list.appendChild(dragged);});
 list.addEventListener('drop',function(e){if(!dragged||dragged.parentElement!==list)return;e.preventDefault();});
});
var save=document.getElementById('saveMenuOrder'),state=document.getElementById('saveMenuState');
if(save)save.addEventListener('click',async function(){
 var tree={header:[],footer:[]};
 document.querySelectorAll('.root-list').forEach(function(root){var loc=root.dataset.location;Array.from(root.querySelectorAll(':scope > .menu-node')).forEach(function(node){var children=node.querySelector(':scope > .child-list');tree[loc].push({id:Number(node.dataset.id),children:children?Array.from(children.querySelectorAll(':scope > .menu-node')).map(function(ch){return Number(ch.dataset.id)}):[]});});});
 var csrf=document.querySelector('input[name="_csrf"]');if(!csrf){state.textContent='Güvenlik anahtarı bulunamadı.';return;}
 save.disabled=true;state.textContent='Kaydediliyor…';
 try{var body=new FormData();body.append('_csrf',csrf.value);body.append('tree',JSON.stringify(tree));var response=await fetch('/admin/navigation/reorder',{method:'POST',body:body,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});var data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Sıralama kaydedilemedi.');state.textContent='Sıralama kaydedildi.';}
 catch(err){state.textContent=err.message||'Bir hata oluştu.';}
 finally{save.disabled=false;}
});
})();
</script></body></html>